      stack.pop();
      current = frame.parent;
      continue;
    }

    current.push({ type: "value", path: tag, escaped: true, position });
  }

  const unclosed = stack.at(-1)?.block;
  if (unclosed) {
    throw syntaxError(
      source,
      unclosed.position.offset,
      `Unclosed '${unclosed.type}' block`,
