  offset: number;
  line: number;
  column: number;
};

type TextNode = { type: "text"; value: string };
type ValueNode = { type: "value"; path: string; escaped: boolean; position: Position };
type BlockNode = {
  type: "if" | "each";
  path: string;
  body: Node[];
  alternate: Node[];
  hasElse: boolean;
  position: Position;
};
type Node = TextNode | ValueNode | BlockNode;

type Frame = {
  block: BlockNode;
  parent: Node[];
};

type Context = {
  root: unknown;
  value: unknown;
  index?: number;
  inEach: boolean;
};

const MISSING = Symbol("missing");

function positionAt(source: string, offset: number): Position {
  let line = 1;
  let column = 1;

  for (let i = 0; i < offset; i++) {
    if (source.charCodeAt(i) === 10) {
      line++;
      column = 1;
    } else {
      column++;
    }
  }

  return { offset, line, column };
}

function syntaxError(source: string, offset: number, message: string): Error {
  const { line, column } = positionAt(source, offset);
  return new Error(`${message} at line ${line}, column ${column}`);
}

